INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass LCD-Bildschirme immer weniger Strom als LEDs verbrauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "LEDs sind effizienter"}, {"text": "Ja", "correct": false, "because": "LCDs brauchen Hintergrundbeleuchtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen LCD-Bildschirm für IT-Arbeit auswähle?', 3, '[{"text": "Auflösung", "correct": true, "because": "Wichtig für Detailarbeit"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Farbe des Rahmens", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen einen LCD-Bildschirm nützlich?', 5, '[{"text": "Hohe Farbgenauigkeit", "correct": true, "because": "Wichtig für Grafik"}, {"text": "Geringer Stromverbrauch", "correct": true, "because": "Effizienter Betrieb"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Schwere Bauweise", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) LCDs nutzen Flüssigkristalle. b) Sie haben immer bessere Kontraste als OLEDs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "OLEDs haben besseren Kontrast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen LCD für Programmierung auswähle?', 4, '[{"text": "Bildwiederholrate", "correct": false, "because": "Wichtig für Flüssigkeit"}, {"text": "Auflösung", "correct": false, "because": "Entscheidend für Lesbarkeit"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob LCD-Bildschirme immer flimmern?', 2, '[{"text": "Nein", "correct": true, "because": "Flimmern abhängig von Modell"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich einen LCD für IT-Schulungen nutze?', 3, '[{"text": "Klarheit der Darstellung", "correct": true, "because": "Fördert Verständnis"}, {"text": "Maximale Helligkeit", "correct": false, "because": "Sekundär"}, {"text": "Geringes Gewicht", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einem LCD für Grafikdesign entscheidend?', 5, '[{"text": "Farbtreue", "correct": true, "because": "Genauigkeit essenziell"}, {"text": "Große Farbtiefe", "correct": true, "because": "Detailwiedergabe"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Kleiner Bildschirm", "correct": false, "because": "Erschwert Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) LCDs sind flacher als CRTs. b) Sie haben immer längere Lebensdauer als OLEDs. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "OLEDs langlebiger möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich einen LCD für IT-Arbeit auswähle?', 4, '[{"text": "Hohe Auflösung", "correct": false, "because": "Wichtig für Details"}, {"text": "Gute Blickwinkel", "correct": false, "because": "Fördert Lesbarkeit"}, {"text": "Dekorativer Rahmen", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind LCD-Bildschirme immer teurer als LEDs?', 2, '[{"text": "Nein", "correct": true, "because": "Preis variiert"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein LCD gegenüber älteren Technologien?', 4, '[{"text": "Geringerer Stromverbrauch", "correct": true, "because": "Effizienter als CRT"}, {"text": "Flache Bauweise", "correct": true, "because": "Platzsparend"}, {"text": "Hohe Latenz", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass LCDs keine Hintergrundbeleuchtung brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hintergrundbeleuchtung essenziell"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen LCD für Programmierung auszuwählen?', 3, '[{"text": "Matte Oberfläche", "correct": true, "because": "Reduziert Reflexionen"}, {"text": "Hoher Glanz", "correct": false, "because": "Stört Sicht"}, {"text": "Bunte Rahmen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) LCDs haben geringere Reaktionszeiten als OLEDs. b) Sie sind leichter als CRTs.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "OLEDs schneller"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einem LCD für IT-Arbeit?', 5, '[{"text": "Bildschirmgröße", "correct": true, "because": "Fördert Übersicht"}, {"text": "Reaktionszeit", "correct": true, "because": "Wichtig für Dynamik"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Rahmenfarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen LCD für Netzwerküberwachung nutze?', 3, '[{"text": "Auflösung", "correct": false, "because": "Wichtig für Details"}, {"text": "Kontrast", "correct": false, "because": "Fördert Lesbarkeit"}, {"text": "Dekoratives Design", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Haben LCDs immer schlechtere Farben als OLEDs?', 3, '[{"text": "Ja", "correct": true, "because": "OLEDs bieten bessere Farben"}, {"text": "Nein", "correct": false, "because": "High-End-LCDs können mithalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob LCDs für Gaming ungeeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Reaktionszeit"}, {"text": "Ja", "correct": false, "because": "Geeignet bei guten Specs"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend, wenn ich einen LCD für IT-Arbeit kaufe?', 4, '[{"text": "Hohe Auflösung", "correct": true, "because": "Fördert Präzision"}, {"text": "Maximale Helligkeit", "correct": false, "because": "Sekundär"}, {"text": "Dekorativer Standfuß", "correct": false, "because": "Irrelevant"}]');
